use std::{fs,path::Path};use serde_json::{Value,json};use sha2::{Digest,Sha256};fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/early-x175");fs::rename(r.join("native"),r.join("initial-native")).unwrap();for f in["build-plan.json","build-pins.json","field.rs","field-tests.rs","finish.rs"]{fs::copy(r.join(f),r.join(format!("{f}.initial"))).unwrap();}for f in["field.rs","source/crates/zopro-bn254/src/early_x.rs"]{let p=r.join(f);let s=fs::read_to_string(&p).unwrap().replacen("//! Canonical native","// Canonical native",1).replace("use ark_ff::{Field,UniformRand};","use ark_ff::{Field,UniformRand,AdditiveGroup};");fs::write(p,s).unwrap();}let p=r.join("field-tests.rs");let s=fs::read_to_string(&p).unwrap().replace("use ark_ff::{Field,UniformRand};","use ark_ff::{Field,UniformRand,AdditiveGroup};");fs::write(p,s).unwrap();for f in["finish.rs","source/crates/zopro-core/src/msm/early_x.rs"]{let p=r.join(f);let s=fs::read_to_string(&p).unwrap().replace("pub(super) fn g1(","#[inline(always)]\npub(super) fn g1(").replace("pub(super) fn g2(","#[inline(always)]\npub(super) fn g2(");fs::write(p,s).unwrap();}let p=r.join("build-plan.json");let mut plan:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();plan["steps"]=json!(plan["steps"].as_array().unwrap().iter().filter(|s|!s["name"].as_str().unwrap().ends_with("-off")).cloned().collect::<Vec<_>>());assert_eq!(plan["steps"].as_array().unwrap().len(),6);fs::write(p,serde_json::to_vec_pretty(&plan).unwrap()).unwrap();let info=json!({"initial_successful_steps":["field-off","core-off","libraries-off","freeze-off","link-off"],"initial_field_ON_compile_errors":["E0753 innerdoc in include","E0599 missingAdditiveGroupimport"],"initial_ON_tests_executed":0,"SDK_requests":0,"changes":"include comment and trait import; force inline new core finishers before their first build to preserve caller boundary","algorithm_changed":false,"OFF_work_reused_without_repeat":true});fs::write(r.join("build-repair.json"),serde_json::to_vec_pretty(&info).unwrap()).unwrap();let p=r.join("build-pins.json");let mut pins:Value=serde_json::from_slice(&fs::read(&p).unwrap()).unwrap();for f in["field.rs","field-tests.rs","finish.rs","source/crates/zopro-bn254/src/early_x.rs","source/crates/zopro-core/src/msm/early_x.rs","repair-build.rs","build-repair.json","repair-setup.rs","setup.initial.rs","setup-initial-failure.json"]{let p=r.join(f);pins[p.display().to_string()]=json!(format!("{:x}",Sha256::digest(fs::read(&p).unwrap())));}fs::write(p,serde_json::to_vec_pretty(&pins).unwrap()).unwrap();}
